// predicate — the predicating morphism.
//
// Input:  { potential-aperiodic-articulation-cell } where the cell is the uncharged
//         position carrier.
// Output: transfinite-predication-category — the codomain object generated by
//         predicating at the token/claim position carried by the utterance,
//         including the predication-fiber-functor precursor later packaged by
//         positing as predication-fibration.
//
// Downstream positing presentations classify datums by their
// aperiodic-articulation-cell shape:
//   datum = potential-aperiodic-articulation-cell -> potential-scott-continuous-posit-cell
//   datum = active-aperiodic-articulation-cell    -> active-scott-continuous-posit-cell
//   datum = stable-aperiodic-articulation-cell    -> stable-scott-continuous-posit-cell
//   datum = absurd-aperiodic-articulation-cell    -> absurd-scott-continuous-posit-cell
//
// Prior revisions: (a) encoded predicating as a recursive
// [input, articulate(input)] pair (re-using articulating's act-structure);
// (b) typed the datum as an abstract {pos: boolean, neg: boolean} object.
// Both are gone; the datum is an aperiodic-articulation-cell because nothing in the
// active tree may live as a typed-by-raw-primitives object — every
// datum-schema must be derived from articulating's primitives.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import Ajv2020 from 'ajv/dist/2020.js';

const load = (alias) =>
  JSON.parse(readFileSync(fileURLToPath(import.meta.resolve(alias)), 'utf8'));

const TOKEN_SCHEMA = load('#active-library/token/token.schema.json');
const CLAIM_SCHEMA = load('#active-library/claim/claim.schema.json');
const TOKEN_SLOT_SCHEMA = load('#articulating/library/aperiodic-articulation-category/library/aperiodic-articulation-cell/library/token-articulation-slot/token-articulation-slot.schema.json');
const CLAIM_SLOT_SCHEMA = load('#articulating/library/aperiodic-articulation-category/library/aperiodic-articulation-cell/library/claim-articulation-slot/claim-articulation-slot.schema.json');
const UTTERANCE_SCHEMA = load('#active-library/utterance/utterance.schema.json');
const APERIODIC_ARTICULATION_CELL_SCHEMA = load('#articulating/library/aperiodic-articulation-category/library/aperiodic-articulation-cell/aperiodic-articulation-cell.schema.json');
const POTENTIAL_CELL_SCHEMA = load('#articulating/library/aperiodic-articulation-category/library/aperiodic-articulation-cell/library/potential-aperiodic-articulation-cell/potential-aperiodic-articulation-cell.schema.json');
const ENTITY_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/library/category/library/entity-set/library/entity/entity.schema.json');
const ENTITY_SET_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/library/category/library/entity-set/entity-set.schema.json');
const PREDICATE_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate/predicate.schema.json');
const PREDICATE_SET_SCHEMA = load('#predication-cell-set/library/predicate-set/predicate-set.schema.json');
const PREDICATE_CATEGORY_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/predicate-category.schema.json');
const SPECIALIZATION_PAIR_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/specializing/library/specialization-pair/specialization-pair.schema.json');
const CONVERSE_PAIR_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/conversing/library/converse-pair/converse-pair.schema.json');
const SUBJECT_PROJECTION_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/projecting-to-subject/library/subject-projection/subject-projection.schema.json');
const OBJECT_PROJECTION_SCHEMA = load('#predication-cell-set/library/predicate-set/library/predicate-category/projecting-to-object/library/object-projection/object-projection.schema.json');
const PREDICATION_CELL_SET_SCHEMA = load('#predication-cell-set/predication-cell-set.schema.json');
const BILATTICE_SCHEMA = load('#bilattice/bilattice.schema.json');
const PREDICATION_FIBER_FUNCTOR_SCHEMA = load('#predication-fiber-functor/predication-fiber-functor.schema.json');
const TRANSFINITE_PREDICATION_CATEGORY_SCHEMA = load('#transfinite-predication-category/transfinite-predication-category.schema.json');
const PREDICATING_SCHEMA = load('#predicating/predicating.schema.json');

const ajv = new Ajv2020({ allErrors: true, strict: false });
for (const schema of [
  TOKEN_SCHEMA,
  CLAIM_SCHEMA,
  TOKEN_SLOT_SCHEMA,
  CLAIM_SLOT_SCHEMA,
  UTTERANCE_SCHEMA,
  APERIODIC_ARTICULATION_CELL_SCHEMA,
  POTENTIAL_CELL_SCHEMA,
  ENTITY_SCHEMA,
  ENTITY_SET_SCHEMA,
  PREDICATE_SCHEMA,
  PREDICATE_SET_SCHEMA,
  SPECIALIZATION_PAIR_SCHEMA,
  CONVERSE_PAIR_SCHEMA,
  SUBJECT_PROJECTION_SCHEMA,
  OBJECT_PROJECTION_SCHEMA,
  PREDICATE_CATEGORY_SCHEMA,
  PREDICATION_CELL_SET_SCHEMA,
  BILATTICE_SCHEMA,
  PREDICATION_FIBER_FUNCTOR_SCHEMA,
  TRANSFINITE_PREDICATION_CATEGORY_SCHEMA,
  PREDICATING_SCHEMA,
]) {
  ajv.addSchema(schema);
}

const validateInput = ajv.compile(PREDICATING_SCHEMA.properties.input);
const validateOutput = ajv.compile(TRANSFINITE_PREDICATION_CATEGORY_SCHEMA);

export default function predicate(input) {
  if (!validateInput(input)) {
    throw new TypeError(
      `predicate: input violates predicating domain schema: ${ajv.errorsText(validateInput.errors)}`,
    );
  }
  const cell = input['potential-aperiodic-articulation-cell'];
  if (aperiodicArticulationCellClass(cell) !== 'potential') {
    throw new TypeError('predicate: input.potential-aperiodic-articulation-cell must be a potential-aperiodic-articulation-cell');
  }
  const [token, claim] = cell[0];
  const entitySet = Object.freeze({
    entities: Object.freeze([token]),
  });
  const predicateSet = Object.freeze({
    predicates: Object.freeze([claim]),
  });
  const cellSet = Object.freeze({
    'entity-set': entitySet,
    'predicate-set': predicateSet,
  });
  const base = initialPredicateCategory(predicateSet);
  const output = Object.freeze({
    'predication-cell-set': cellSet,
    'predication-fiber-functor': Object.freeze({
      'cell-set': cellSet,
      base,
      'entity-set': entitySet,
      bilattice: Object.freeze({}),
    }),
  });
  if (!validateOutput(output)) {
    throw new TypeError(
      `predicate: output violates transfinite-predication-category schema: ${ajv.errorsText(validateOutput.errors)}`,
    );
  }
  return output;
}

function initialPredicateCategory(predicateSet) {
  return Object.freeze({
    objects: predicateSet,
    specialization: Object.freeze([]),
    converse: Object.freeze([]),
    'subject-projection': Object.freeze([]),
    'object-projection': Object.freeze([]),
  });
}

// Classify a candidate datum by its aperiodic-articulation-cell shape.
// Returns 'potential' | 'active' | 'stable' | 'absurd' | null.
export function aperiodicArticulationCellClass(datum) {
  if (!Array.isArray(datum) || datum.length !== 2) return null;
  const [carrier, pairing] = datum;
  if (!Array.isArray(carrier) || carrier.length !== 2) return null;
  if (!Array.isArray(pairing) || pairing.length !== 2) return null;
  const hasToken = filledWith(pairing[0], carrier[0]);
  const hasClaim = filledWith(pairing[1], carrier[1]);
  if ((Array.isArray(pairing[0]) && pairing[0].length === 1 && !hasToken) ||
      (Array.isArray(pairing[1]) && pairing[1].length === 1 && !hasClaim)) {
    return null;
  }
  if (!hasToken && !hasClaim) return 'potential';
  if (hasToken && !hasClaim) return 'active';
  if (!hasToken && hasClaim) return 'stable';
  return 'absurd';
}

function filledWith(slot, value) {
  return Array.isArray(slot) &&
    slot.length === 1 &&
    (slot[0] === value || JSON.stringify(slot[0]) === JSON.stringify(value));
}
